<script setup>
import GuestLayout from '@/Layouts/GuestLayout.vue';
import { Head, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
const props=defineProps({ email:String, token:String }); const show=ref(false); const form=useForm({ token:props.token,email:props.email,password:'',password_confirmation:'' }); const submit=()=>form.post(route('password.store'),{onFinish:()=>form.reset('password','password_confirmation')});
</script>
<template><Head title="تعيين كلمة مرور جديدة"/><GuestLayout title="كلمة مرور جديدة" description="اختر كلمة مرور قوية لحماية بيانات فنانة فون."><form class="space-y-4" @submit.prevent="submit"><div><label class="mb-1 block text-sm font-semibold text-slate-700 dark:text-slate-300">البريد الإلكتروني</label><input v-model="form.email" type="email" readonly class="w-full rounded-xl border-slate-300 bg-slate-100 py-3 text-slate-600 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"/><p v-if="form.errors.email" class="mt-1 text-xs text-rose-600">{{ form.errors.email }}</p></div><div><label class="mb-1 block text-sm font-semibold text-slate-700 dark:text-slate-300">كلمة المرور الجديدة</label><div class="relative"><input v-model="form.password" :type="show?'text':'password'" autocomplete="new-password" class="w-full rounded-xl border-slate-300 py-3 pl-14 focus:border-indigo-500 focus:ring-indigo-500 dark:border-slate-700 dark:bg-slate-950 dark:text-white"/><button type="button" class="absolute inset-y-0 left-0 px-4 text-xs font-bold text-slate-500" @click="show=!show">{{show?'إخفاء':'إظهار'}}</button></div><p v-if="form.errors.password" class="mt-1 text-xs text-rose-600">{{ form.errors.password }}</p></div><div><label class="mb-1 block text-sm font-semibold text-slate-700 dark:text-slate-300">تأكيد كلمة المرور</label><input v-model="form.password_confirmation" :type="show?'text':'password'" autocomplete="new-password" class="w-full rounded-xl border-slate-300 py-3 focus:border-indigo-500 focus:ring-indigo-500 dark:border-slate-700 dark:bg-slate-950 dark:text-white"/></div><button :disabled="form.processing" class="w-full rounded-xl bg-indigo-600 px-5 py-3.5 font-bold text-white hover:bg-indigo-700 disabled:opacity-50">{{form.processing?'جارٍ الحفظ...':'حفظ كلمة المرور'}}</button></form></GuestLayout></template>
